// mainwindow.cpp
#include "mainwindow.h"
#include "ui_mainwindow.h"
#include <QAxObject>
#include <QFileInfo>
#include <QVector>

MainWindow::MainWindow(QWidget *parent)
    : QMainWindow(parent)
    , ui(new Ui::MainWindow)
{
    ui->setupUi(this);
    setWindowTitle("Excel to CSV Converter");

    // Configure UI elements
    ui->statusLabel->setText("Ready to convert Excel files to CSV");
    ui->selectDirButton->setText("Select Directory");
}

MainWindow::~MainWindow()
{
    delete ui;
}

void MainWindow::on_selectDirButton_clicked()
{
    // Get directory from user
    QString dirPath = QFileDialog::getExistingDirectory(
        this,
        "Select Directory with Excel Files",
        QDir::homePath()
    );

    if (dirPath.isEmpty()) {
        ui->statusLabel->setText("Operation cancelled");
        return;
    }

    // Create output directory
    QString outputDir = dirPath + "/CSV_Files";
    if (!QDir().mkpath(outputDir)) {
        QMessageBox::critical(this, "Error", "Could not create output directory");
        return;
    }

    // Find Excel files
    QDir dir(dirPath);
    QStringList filters;
    filters << "*.xls" << "*.xlsx" << "*.xlsm";
    QFileInfoList excelFiles = dir.entryInfoList(filters, QDir::Files);

    if (excelFiles.isEmpty()) {
        QMessageBox::information(this, "No Files", "No Excel files found in selected directory");
        return;
    }

    // Setup progress dialog
    QProgressDialog progressDialog("Converting files...", "Cancel", 0, excelFiles.size(), this);
    progressDialog.setWindowModality(Qt::WindowModal);
    progressDialog.setMinimumDuration(0);

    // Process each Excel file
    int successCount = 0;
    for (int i = 0; i < excelFiles.size(); ++i) {
        if (progressDialog.wasCanceled()) break;

        QString excelPath = excelFiles[i].absoluteFilePath();
        QString csvPath = outputDir + "/" + excelFiles[i].baseName() + ".csv";

        if (convertExcelToCsv(excelPath, csvPath)) {
            successCount++;
        } else {
            ui->statusLabel->setText("Error converting: " + excelFiles[i].fileName());
        }

        progressDialog.setValue(i + 1);
        progressDialog.setLabelText("Converted " + QString::number(i + 1) + 
                                  " of " + QString::number(excelFiles.size()) + 
                                  " files");
        qApp->processEvents(); // Keep UI responsive
    }

    // Show completion message
    if (progressDialog.wasCanceled()) {
        ui->statusLabel->setText("Conversion cancelled by user");
    } else {
        QString message = QString("Conversion completed! %1 files converted to %2")
                          .arg(successCount)
                          .arg(outputDir);
        ui->statusLabel->setText(message);
        QMessageBox::information(this, "Success", message);
    }
}

bool MainWindow::convertExcelToCsv(const QString &excelPath, const QString &csvPath)
{
    // Check for Windows and Excel availability
    #if !defined(Q_OS_WIN)
    Q_UNUSED(excelPath);
    Q_UNUSED(csvPath);
    return false;
    #else
    QAxObject excel("Excel.Application");
    if (excel.isNull()) {
        return false; // Excel not available
    }

    try {
        excel.setProperty("Visible", false);
        excel.setProperty("DisplayAlerts", false);

        QAxObject *workbooks = excel.querySubObject("Workbooks");
        QAxObject *workbook = workbooks->querySubObject(
            "Open(const QString&, QVariant, QVariant)", 
            excelPath, 
            true,   // UpdateLinks = false
            true    // ReadOnly = true
        );

        if (!workbook) {
            throw std::runtime_error("Could not open workbook");
        }

        // Activate first worksheet
        QAxObject *sheets = workbook->querySubObject("Worksheets");
        QAxObject *sheet = sheets->querySubObject("Item(int)", 1);
        if (!sheet) {
            throw std::runtime_error("No worksheets found");
        }
        sheet->dynamicCall("Activate()");

        // Save as CSV (6 = xlCSV)
        workbook->dynamicCall("SaveAs(const QString&, int)", csvPath, 6);

        // Clean up
        workbook->dynamicCall("Close(bool)", false);
        excel.dynamicCall("Quit()");

        return true;
    } 
    catch (...) {
        excel.dynamicCall("Quit()");
        return false;
    }
    #endif
}
